#!/usr/bin/env Rscript
# Frozen objects, animal-aware summaries, fixed candidate set, new Figure 9 only.
if (!("--render-only" %in% commandArgs(trailingOnly=TRUE))) {
suppressPackageStartupMessages({library(ape);library(phylolm);library(phylopath);library(dplyr);library(readr);library(tidyr);library(jsonlite)})
set.seed(2026092409)
RUN<-normalizePath(getwd());stopifnot(basename(RUN)=='manuscript_story_20260924_01')
OUT<-file.path(RUN,'figures/figure_9/analysis');SNAP<-file.path(RUN,'inputs/animal_robustness')
sha<-function(x) sub(' .*','',system2('sha256sum',shQuote(x),stdout=TRUE))
sources<-c(morphology='inputs/datasets/Supplementary_Data_S18_frozen_cell_nucleus_objects.csv',iod='inputs/datasets/Supplementary_Data_S21_frozen_nuclear_iod_objects.csv',traits='figures/figure_8/analysis/traits_joined.csv',scaling='figures/figure_8/analysis/scaling.csv',baseline_rankings='figures/figure_8/analysis/path_model_comparison.csv',baseline_coefficients='figures/figure_8/analysis/regression_coefficients.csv',tree='inputs/body_size/path24_time_tree.nwk')
sources<-setNames(file.path(RUN,sources),names(sources));dest<-setNames(file.path(SNAP,paste0(names(sources),ifelse(grepl('nwk$',sources),'.nwk','.csv'))),names(sources))
for(id in names(sources)){stopifnot(file.exists(sources[[id]]));if(!file.exists(dest[[id]]))stopifnot(file.copy(sources[[id]],dest[[id]]));stopifnot(identical(sha(sources[[id]]),sha(dest[[id]])))}
manifest<-tibble(source_id=names(sources),source_path=unname(sources),snapshot_path=unname(dest),sha256=vapply(dest,sha,character(1)));write_csv(manifest,file.path(SNAP,'MANIFEST.csv'))
rd<-function(id)read_csv(dest[[id]],show_col_types=FALSE,progress=FALSE)
wr<-function(x,name)write_csv(x,file.path(OUT,paste0(name,'.csv')))
traits<-rd('traits');scaling<-rd('scaling');tree<-read.tree(dest[['tree']])
morph<-rd('morphology')%>%select(species,specimen_id,filename,nucleus_object_id,cell_area_um2,nuc_area_um2)%>%left_join(traits%>%select(species,tree_tip),by='species')
iod<-rd('iod')%>%select(species,specimen_id,filename,nucleus_object_id,nuc_iod)%>%left_join(traits%>%select(species,tree_tip),by='species')
stopifnot(nrow(traits)==24L,nrow(morph)==1152L,nrow(iod)==805L,!anyNA(morph),!anyNA(iod),n_distinct(morph$specimen_id)==42L,n_distinct(morph$filename)==43L,n_distinct(iod$specimen_id)==50L,n_distinct(iod$filename)==51L,all(morph$cell_area_um2>morph$nuc_area_um2),all(morph$nuc_area_um2>0),all(iod$nuc_iod>0),!anyDuplicated(morph$nucleus_object_id),!anyDuplicated(iod$nucleus_object_id),setequal(morph$tree_tip,traits$tree_tip),setequal(iod$tree_tip,traits$tree_tip))
identity<-bind_rows(morph%>%select(tree_tip,specimen_id,filename),iod%>%select(tree_tip,specimen_id,filename))%>%distinct()
stopifnot(all(identity%>%group_by(specimen_id)%>%summarise(n=n_distinct(tree_tip))%>%pull(n)==1L),all(identity%>%group_by(filename)%>%summarise(n=n_distinct(specimen_id))%>%pull(n)==1L))
ma<-morph%>%group_by(species,tree_tip,specimen_id)%>%summarise(n_objects=n(),n_images=n_distinct(filename),cell_area_um2=median(cell_area_um2),nucleus_area_um2=median(nuc_area_um2),.groups='drop')
ii<-iod%>%group_by(species,tree_tip,specimen_id,filename)%>%summarise(n_objects=n(),median_iod=median(nuc_iod),.groups='drop')
ia<-ii%>%group_by(species,tree_tip,specimen_id)%>%summarise(n_objects=sum(n_objects),n_images=n(),mean_image_median_iod=mean(median_iod),.groups='drop')
wr(ma,'morphology_animal_summaries');wr(ii,'iod_image_summaries');wr(ia,'iod_animal_summaries')
support<-bind_rows(ma%>%mutate(assay='Paired morphology'),ia%>%mutate(assay='Nuclear IOD'))%>%group_by(species,tree_tip,assay)%>%summarise(n_animals=n(),n_images=sum(n_images),max_animal_fraction=max(n_objects)/sum(n_objects),n_objects=sum(n_objects),single_animal=n()==1L,.groups='drop');stopifnot(all(support$max_animal_fraction<=1),all(support$max_animal_fraction>=1/support$n_animals-1e-12),all(support$max_animal_fraction[support$n_animals==1]==1),all(support$max_animal_fraction[support$n_animals>1]<1));wr(support,'species_support')
overlap<-morph%>%distinct(tree_tip,specimen_id)%>%inner_join(iod%>%distinct(tree_tip,specimen_id),by=c('tree_tip','specimen_id'));wr(overlap,'shared_assay_animals')
poolm<-morph%>%group_by(tree_tip)%>%summarise(c=median(cell_area_um2),n=median(nuc_area_um2),.groups='drop')
pooli<-ii%>%group_by(tree_tip)%>%summarise(iod=mean(median_iod),.groups='drop')
balm<-ma%>%group_by(tree_tip)%>%summarise(c=median(cell_area_um2),n=median(nucleus_area_um2),.groups='drop')
bali<-ia%>%group_by(tree_tip)%>%summarise(iod=mean(mean_image_median_iod),.groups='drop')
anchor<-16.1/.978
raw_traits<-function(ms,is){d<-traits%>%select(species,tree_tip,b=max_svl_mm)%>%left_join(ms,by='tree_tip')%>%left_join(is,by='tree_tip');d$g<-d$iod/d$iod[d$tree_tip=='fuscus']*anchor;stopifnot(nrow(d)==24L,!anyNA(d),all(as.matrix(d[,c('b','g','c','n')])>0));d}
baseline<-raw_traits(poolm,pooli);balanced<-raw_traits(balm,bali)
stopifnot(max(abs(baseline$c-traits$cell_area_um2))<1e-8,max(abs(baseline$n-traits$nucleus_area_um2))<1e-8,max(abs(baseline$g-traits$genome_size_pg_fuscus_anchored))<1e-7)
wr(bind_rows(baseline%>%mutate(aggregation='released'),balanced%>%mutate(aggregation='animal_balanced')),'species_traits_raw')
changes<-baseline%>%select(tree_tip,g,c,n)%>%pivot_longer(-tree_tip,names_to='trait',values_to='released')%>%left_join(balanced%>%select(tree_tip,g,c,n)%>%pivot_longer(-tree_tip,names_to='trait',values_to='animal_balanced'),by=c('tree_tip','trait'))%>%mutate(percent_change=100*(animal_balanced/released-1));wr(changes,'species_estimate_changes')
standardize<-function(d){for(v in c('b','g','c','n')){s<-scaling[scaling$variable==v,];d[[v]]<-(log10(d[[v]])-s$full24_mean)/s$full24_sd};d}
stopifnot(max(abs(standardize(baseline)$b-traits$b))<1e-12,max(abs(standardize(baseline)$g-traits$g))<1e-8)
models<-define_model_set(body_only=c(g~b,c~b,n~b),cell_bridge=c(g~b,c~b+g,n~b+c),nucleus_bridge=c(g~b,n~b+g,c~b+n),genome_bridge=c(g~b,c~b+g,n~b+g))
forms<-list(genome_to_cell_body_adjusted=c~g+b,cell_to_nucleus_body_adjusted=n~c+b,genome_and_cell_to_nucleus_body_adjusted=n~g+c+b)
warning_rows<-failure_rows<-list()
fit_warn<-function(expr,mode,id,fit_id)withCallingHandlers(expr,warning=function(w){warning_rows[[length(warning_rows)+1L]]<<-tibble(mode=mode,id=as.character(id),fit_id=fit_id,warning=conditionMessage(w));invokeRestart('muffleWarning')})
fit_dataset<-function(raw,mode,id,panel,aggregation){
 d<-standardize(raw);phy<-keep.tip(tree,d$tree_tip);df<-as.data.frame(d[,c('b','g','c','n')]);rownames(df)<-d$tree_tip;df<-df[phy$tip.label,,drop=FALSE];stopifnot(identical(rownames(df),phy$tip.label));rr<-list()
 for(k in names(forms)){f<-fit_warn(phylolm(forms[[k]],data=df,phy=phy,model='lambda',lower.bound=1e-7,upper.bound=1),mode,id,k);co<-as.data.frame(summary(f)$coefficients);ci<-qt(.975,f$n-f$d);rr[[k]]<-tibble(mode=mode,id=as.character(id),panel=panel,aggregation=aggregation,relation_id=k,equation=paste(deparse(forms[[k]]),collapse=' '),term=rownames(co),estimate=co$Estimate,standard_error=co$StdErr,ci_low=co$Estimate-ci*co$StdErr,ci_high=co$Estimate+ci*co$StdErr,p_value=co$p.value,lambda=as.numeric(f$optpar),lambda_boundary=as.numeric(f$optpar)<1.01e-7|as.numeric(f$optpar)>.999999,n_species=f$n,residual_df=f$n-f$d)}
 path<-fit_warn(phylo_path(models,data=df,tree=phy,model='lambda',lower.bound=1e-7,upper.bound=1),mode,id,'path')
 if(length(path$warnings))for(w in unlist(path$warnings,use.names=FALSE))warning_rows[[length(warning_rows)+1L]]<<-tibble(mode=mode,id=as.character(id),fit_id='path_stored',warning=w)
 rank<-as_tibble(as.data.frame(summary(path)))%>%mutate(mode=mode,id=as.character(id),panel=panel,aggregation=aggregation,rank=row_number(),n_species=nrow(df))
 ds<-bind_rows(lapply(names(path$d_sep),function(m){x<-path$d_sep[[m]];tibble(mode=mode,id=as.character(id),panel=panel,aggregation=aggregation,model=m,claim=x$d_sep,p_value=x$p,lambda=x$phylo_par)}))
 stopifnot(nrow(rank)==4L,abs(sum(rank$w)-1)<1e-10,all(rank$q+1<rank$n_species),all(is.finite(rank$CICc)))
 list(coef=bind_rows(rr),rank=rank,dsep=ds)
}
results<-list()
for(ag in c('released','animal_balanced'))for(pa in c('full24','subset22')){d<-if(ag=='released')baseline else balanced;if(pa=='subset22')d<-d[!d$tree_tip%in%c('aeneus','wrighti'),];results[[paste(ag,pa)]]<-fit_dataset(d,'point',paste(ag,pa,sep='/'),pa,ag)}
pointcoef<-bind_rows(lapply(results,`[[`,'coef'));pointrank<-bind_rows(lapply(results,`[[`,'rank'));wr(pointcoef,'point_coefficients');wr(pointrank,'point_model_comparison');wr(bind_rows(lapply(results,`[[`,'dsep')),'point_dsep')
ref<-rd('baseline_rankings')%>%filter(candidate_set=='body_adjusted_four')%>%select(panel,model,reference_CICc=CICc,reference_weight=w)
repro<-pointrank%>%filter(aggregation=='released')%>%left_join(ref,by=c('panel','model'))%>%mutate(CICc_difference=CICc-reference_CICc,weight_difference=w-reference_weight)
stopifnot(max(abs(repro$CICc_difference))<1e-6,max(abs(repro$weight_difference))<1e-7)
rc<-rd('baseline_coefficients')%>%select(panel,relation_id,term,reference_estimate=standardized_coefficient)
cr<-pointcoef%>%filter(aggregation=='released')%>%left_join(rc,by=c('panel','relation_id','term'));stopifnot(!anyNA(cr$reference_estimate),max(abs(cr$estimate-cr$reference_estimate))<1e-7);wr(repro,'released_reproduction_check')
# Independent per-assay animal draws: do not infer cross-assay covariance.
make_groups<-function(z)lapply(split(z,z$tree_tip),function(s)lapply(split(s,s$specimen_id),function(a)split(a,a$filename)))
mg<-make_groups(morph);ig<-make_groups(iod)
sample_morph<-function(groups){animals<-sample.int(length(groups),length(groups),replace=TRUE);values<-vapply(animals,function(a){images<-groups[[a]];ii<-sample.int(length(images),length(images),replace=TRUE);z<-bind_rows(lapply(ii,function(i){im<-images[[i]];im[sample.int(nrow(im),nrow(im),replace=TRUE),,drop=FALSE]}));c(c=median(z$cell_area_um2),n=median(z$nuc_area_um2))},numeric(2));c(c=median(values[1,]),n=median(values[2,]))}
sample_iod<-function(groups){animals<-sample.int(length(groups),length(groups),replace=TRUE);mean(vapply(animals,function(a){images<-groups[[a]];ii<-sample.int(length(images),length(images),replace=TRUE);mean(vapply(ii,function(i){im<-images[[i]];median(im$nuc_iod[sample.int(nrow(im),nrow(im),replace=TRUE)])},numeric(1)))},numeric(1)))}
B<-250L;bootcoef<-bootrank<-bootds<-boottraits<-vector('list',B)
for(rep in seq_len(B)){
 mm<-bind_rows(lapply(names(mg),function(s){v<-sample_morph(mg[[s]]);tibble(tree_tip=s,c=v[['c']],n=v[['n']])}));gg<-tibble(tree_tip=names(ig),iod=vapply(ig,sample_iod,numeric(1)));raw<-raw_traits(mm,gg);boottraits[[rep]]<-raw%>%mutate(replicate=rep)
 r<-tryCatch(fit_dataset(raw,'hierarchical_bootstrap',rep,'full24','animal_balanced'),error=function(e){failure_rows[[length(failure_rows)+1L]]<<-tibble(mode='hierarchical_bootstrap',id=as.character(rep),error=conditionMessage(e));NULL})
 if(!is.null(r)){bootcoef[[rep]]<-r$coef;bootrank[[rep]]<-r$rank;bootds[[rep]]<-r$dsep}
 if(rep%%25L==0L){message('Hierarchical resamples: ',rep,'/',B);wr(bind_rows(bootcoef),'bootstrap_coefficients');wr(bind_rows(bootrank),'bootstrap_model_comparison')}
}
wr(bind_rows(boottraits),'bootstrap_species_traits');wr(bind_rows(bootds),'bootstrap_dsep')
loo<-lapply(traits$tree_tip,function(s)tryCatch(fit_dataset(baseline[baseline$tree_tip!=s,],'leave_one_species_out',s,'n23','released'),error=function(e){failure_rows[[length(failure_rows)+1L]]<<-tibble(mode='leave_one_species_out',id=s,error=conditionMessage(e));NULL}))
lc<-bind_rows(lapply(loo,`[[`,'coef'));lr<-bind_rows(lapply(loo,`[[`,'rank'));wr(lc,'leave_one_species_out_coefficients');wr(lr,'leave_one_species_out_model_comparison');wr(bind_rows(lapply(loo,`[[`,'dsep')),'leave_one_species_out_dsep')
bc<-bind_rows(bootcoef);br<-bind_rows(bootrank)
coefsens<-bind_rows(bc,lc)%>%filter(term!='(Intercept)')%>%group_by(mode,relation_id,term)%>%summarise(n_completed=n(),median=median(estimate),q025=quantile(estimate,.025),q975=quantile(estimate,.975),min=min(estimate),max=max(estimate),positive_fraction=mean(estimate>0),interval_above_zero_fraction=mean(ci_low>0),lambda_boundary_fraction=mean(lambda_boundary),.groups='drop')
modelsens<-bind_rows(br,lr)%>%group_by(mode,model)%>%summarise(n_completed=n(),first_ranked=sum(rank==1),competitive=sum(delta_CICc<=2),global_p_ge_05=sum(p>=.05),median_weight=median(w),q025_weight=quantile(w,.025),q975_weight=quantile(w,.975),min_weight=min(w),max_weight=max(w),.groups='drop');wr(coefsens,'coefficient_sensitivity_summary');wr(modelsens,'model_sensitivity_summary')
warnings<-if(length(warning_rows))bind_rows(warning_rows)else tibble(mode=character(),id=character(),fit_id=character(),warning=character());failures<-if(length(failure_rows))bind_rows(failure_rows)else tibble(mode=character(),id=character(),error=character());wr(warnings,'warnings');wr(warnings%>%count(warning,sort=TRUE),'warning_summary');wr(failures,'failures')
stopifnot(nrow(br)==B*4L,nrow(lr)==24L*4L,nrow(failures)==0L,all(bind_rows(boottraits)$g[bind_rows(boottraits)$tree_tip=='fuscus']==anchor),identical(manifest$sha256,vapply(dest,sha,character(1))))
qa<-list(passed=TRUE,seed=2026092409,n_species=24,morphology_objects=nrow(morph),morphology_animals=n_distinct(morph$specimen_id),morphology_images=n_distinct(morph$filename),iod_objects=nrow(iod),iod_animals=n_distinct(iod$specimen_id),iod_images=n_distinct(iod$filename),shared_assay_animals=nrow(overlap),shared_assay_objects=length(intersect(morph$nucleus_object_id,iod$nucleus_object_id)),single_animal_morphology=sum(support$assay=='Paired morphology'&support$single_animal),single_animal_iod=sum(support$assay=='Nuclear IOD'&support$single_animal),bootstrap_attempted=B,bootstrap_completed=n_distinct(br$id),species_deletions_completed=n_distinct(lr$id),n_failures=nrow(failures),n_warning_occurrences=nrow(warnings),animal_fraction_invariants_passed=TRUE,maximum_CICc_reproduction_difference=max(abs(repro$CICc_difference)),maximum_coefficient_reproduction_difference=max(abs(cr$estimate-cr$reference_estimate)),fixed_full24_scaling=TRUE,paired_morphology_resampling=TRUE,independent_assay_resampling=TRUE,source_hashes_unchanged=TRUE)
write_json(qa,file.path(OUT,'verification.json'),pretty=TRUE,auto_unbox=TRUE)
writeLines(c('# Animal-aware robustness of the body-adjusted path analysis','',
'Exploratory sensitivity analysis; frozen objects and prior figures are preserved. These summaries concern the reviewed selected large-cell morphology panel and quality-matched IOD panel, not random samples of all blood cells.','',
'## Estimands','Released morphology: pooled within-species medians. Equal-animal morphology: median across per-animal pooled-object medians for each trait. Cell/nucleus traits always use paired rows. This changes the species estimand and is a sensitivity comparison, not a correction to a known truth.',
'Released IOD: equal-image mean of within-image nuclear-IOD medians. Equal-animal IOD: average image medians within each animal, then average animal summaries. Genome size uses the same 16.1/0.978 pg/1C D. fuscus anchor, recomputing the common denominator per aggregation/draw; anchor and staining-calibration uncertainty remain excluded.','',
'## Fits','All traits log10 transformed and standardized using the original released full24 means/SDs. Pagel-lambda PGLS on the frozen Path24 dated tree. Individual fitted coefficients use 95% t intervals with n minus regression coefficient count degrees of freedom. Retain exactly the original four body-adjusted candidates, all assuming SVL upstream. Weights are relative to this set, not identified causal directions. Fit full24 and the existing 22-species sensitivity excluding aeneus+wrighti under both aggregations.','',
'## Hierarchical measurement sensitivity','250 draws fixed in advance; seed 2026092409. Within each species and assay, sample observed animals with replacement, sample each selected animal\'s images with replacement, then sample rows within each selected image with replacement. Retain original sample size at every level. Morphology cell/nucleus rows stay paired. Combine per-animal morphology medians by median; IOD image medians by mean within animals then mean across animals.',
'Assays are resampled independently even when animal IDs overlap. Cross-assay covariance, including shared objects, is unmodeled. Ranges describe conditional measurement sensitivity rather than full uncertainty. Single-animal species cannot estimate between-animal variability; resampling their images/objects does not manufacture replication. Maximum SVL is fixed without measurement uncertainty.',
'Every measurement draw retains 24 species. Separately, 24 leave-one-species-out fits use released summaries, fixed scaling, and the pruned dated tree. This assesses species leverage rather than specimen uncertainty. No species is deleted from the primary analysis based on results.','',
'## Verification','Checks: exact identity joins, complete positive traits, animal/image nesting, support totals, source-data replay, Figure8 coefficient/ranking reproduction, candidate-weight normalization, finite CICc, fixed fuscus anchor, 250 complete draws, 24 complete deletion fits, source hashes. Warnings/failures retained in CSVs.'),file.path(OUT,'README.md'))
capture.output(sessionInfo(),file=file.path(OUT,'session_info.txt'))
message('Analysis complete.')
}
# Rendering can be repeated independently with --render-only.
source('scripts/common.R')
OUT<-file.path(RUN,'figures/figure_9/analysis')
read_result<-function(n)read_csv(file.path(OUT,paste0(n,'.csv')),show_col_types=FALSE,progress=FALSE)
traits<-read_result('species_traits_raw');support<-read_result('species_support');changes<-read_result('species_estimate_changes')
pointcoef<-read_result('point_coefficients');br<-read_result('bootstrap_model_comparison')%>%mutate(id=as.character(id));lr<-read_result('leave_one_species_out_model_comparison')
style<-theme_gbe()+theme(plot.title=element_text(size=10,face='bold'),plot.subtitle=element_text(size=8,lineheight=1.1),plot.caption=element_text(size=7.5,hjust=0),axis.text.y=element_text(size=7.5),strip.text=element_text(size=8,face='bold'),legend.position='bottom',legend.text=element_text(size=8),plot.margin=margin(6,7,6,7))
sp<-rev(phylogenetic_species_levels(traits$tree_tip))
support$label<-factor(species_label(support$tree_tip),levels=sp)
colors<-c('Paired morphology'=GBE_COLORS[['blue']],'Nuclear IOD'=GBE_COLORS[['vermillion']])
p1<-ggplot(support,aes(x=max_animal_fraction,y=label,fill=assay))+geom_point(position=position_dodge(width=.88),shape=21,colour='white',size=3.5)+geom_text(aes(label=n_animals),show.legend=FALSE,position=position_dodge(width=.88),size=7.5/ggplot2::.pt,family=GBE_FONT,colour='white')+scale_fill_manual(values=colors)+scale_x_continuous(labels=label_percent(accuracy=1),breaks=c(.25,.5,.75,1),limits=c(.23,1.05))+
 labs(title='Animal support',subtitle='Numbers inside points: animals\n42 morphology animals; 50 IOD animals',x='Largest animal share of objects',y=NULL,fill=NULL)+style+guides(fill=guide_legend(nrow=2))
changes$label<-factor(species_label(changes$tree_tip),levels=sp)
changes$trait<-factor(changes$trait,levels=c('g','c','n'),labels=c('Genome size','Cell area','Nucleus area'))
p2<-ggplot(changes,aes(x=percent_change,y=label,colour=trait))+geom_vline(xintercept=0,colour='grey70')+geom_point(position=position_dodge(width=.58),size=1.7)+scale_colour_manual(values=c('Genome size'=GBE_COLORS[['charcoal']],'Cell area'=GBE_COLORS[['blue']],'Nucleus area'=GBE_COLORS[['vermillion']]))+labs(title='Equal-animal summaries',subtitle='Change from released summaries\nAll observed animals retained',x='Change in species summary (%)',y=NULL,colour=NULL)+style+guides(colour=guide_legend(nrow=3))
key<-function(x)x%>%filter((relation_id=='genome_to_cell_body_adjusted'&term=='g')|(relation_id=='cell_to_nucleus_body_adjusted'&term=='c')|(relation_id=='genome_and_cell_to_nucleus_body_adjusted'&term=='g'))%>%mutate(edge=case_when(relation_id=='genome_to_cell_body_adjusted'~'Genome → cell | SVL',relation_id=='cell_to_nucleus_body_adjusted'~'Cell → nucleus | SVL',TRUE~'Genome → nucleus | cell + SVL'),edge=factor(edge,levels=rev(c('Genome → cell | SVL','Cell → nucleus | SVL','Genome → nucleus | cell + SVL'))))
pd<-key(pointcoef)%>%mutate(aggregation=factor(aggregation,levels=c('released','animal_balanced'),labels=c('Released summaries','Equal-animal summaries')),panel=factor(panel,levels=c('full24','subset22'),labels=c('All species (24)','Without aeneus + wrighti (22)')))
p3<-ggplot(pd,aes(x=estimate,y=edge,colour=aggregation))+geom_vline(xintercept=0,linetype=2,colour='grey65')+geom_errorbar(aes(xmin=ci_low,xmax=ci_high),orientation='y',width=.12,position=position_dodge(width=.42))+geom_point(position=position_dodge(width=.42),size=2)+facet_wrap(~panel,ncol=1)+scale_colour_manual(values=c('Released summaries'=GBE_COLORS[['charcoal']],'Equal-animal summaries'=GBE_COLORS[['blue']]))+labs(title='Conditional relationships under both summaries',subtitle='Same full24 log scaling; 95% t intervals',x='Standardized coefficient',y=NULL,colour=NULL)+style
rw<-bind_rows(br,lr)%>%mutate(mode=factor(mode,levels=c('hierarchical_bootstrap','leave_one_species_out'),labels=c('250 animal/image/object resamples','24 species-removal fits')),model=factor(model,levels=c('body_only','nucleus_bridge','genome_bridge','cell_bridge'),labels=c('SVL alone','Nucleus bridge','Genome bridge','Cell bridge')))
rankcounts<-rw%>%group_by(mode,model)%>%summarise(label=paste0(sum(rank==1),'/',n(),' first'),.groups='drop')
p4<-ggplot(rw,aes(x=w,y=model))+geom_boxplot(width=.48,outlier.shape=NA,fill=GBE_COLORS[['blue']],alpha=.2)+geom_point(position=position_jitter(height=.13,width=0,seed=19),alpha=.2,size=.8)+facet_wrap(~mode,ncol=1)+geom_text(data=rankcounts,aes(x=1.08,label=label),hjust=0,size=7.5/ggplot2::.pt,family=GBE_FONT)+scale_x_continuous(breaks=c(0,.5,1),limits=c(-.02,1.50))+labs(title='Model support under measurement and species sensitivity',subtitle='Four candidates; all specify SVL upstream',x='Relative candidate weight',y=NULL)+style
write_csv(pd,file.path(OUT,'displayed_coefficients.csv'));write_csv(rankcounts,file.path(OUT,'displayed_rank_counts.csv'))
legend<-paste('Animal-aware sensitivity of the body-adjusted analysis. (a) Animal counts printed inside points, positioned by the largest animal\'s share of objects in each species and assay; fixed phylogenetic species order. (b) Percent changes when morphology uses the median of animal medians and IOD the equal-animal mean of image medians. (c) Critical conditional PGLS coefficients with 95% t intervals for released and alternate summaries, full24 and the existing 22-species sensitivity. (d) Candidate-weight distributions for 250 hierarchical measurement draws and 24 leave-one-species-out fits; labels count first ranks. SVL is upstream in all four candidates. The morphology panel contains selected reviewed large cells; paired areas remain paired during resampling. Assays are independently resampled; cross-assay covariance is unmodeled. Single-animal species provide no estimate of between-animal uncertainty. Measurement-sensitivity ranges are not complete uncertainty intervals. See analysis/README.md for estimands and anchoring.')
collage<-(p1|p2)/(p3)/(p4)+plot_layout(heights=c(1.62,1,1))+plot_annotation(tag_levels='a')
save_candidate(9,'Animal-aware robustness of the cellular relationships',collage,list(
 a=list(plot=p1,title='Animal support and sample concentration',width_mm=150,height_mm=190,legend='Numbers inside points show contributing animals per species. Horizontal position shows the largest animal share of retained objects in each assay. Seven morphology species and four IOD species have one observed animal. Fixed phylogenetic species order.',alt_text='Species points show one to four animals, with object contributions concentrated to varying degrees in the largest contributing animal.'),
 b=list(plot=p2,title='Species estimates under equal-animal summaries',width_mm=165,height_mm=190,legend='Percent change from released to equal-animal summaries. Cell/nucleus summaries are medians of per-animal medians; IOD averages image medians within animal before averaging animals. The genome anchor is recomputed consistently.',alt_text='Three points per species show changes in genome size, cell area, and nucleus area after animal-balanced aggregation.'),
 c=list(plot=p3,title='Conditional relationships under both summaries',width_mm=180,height_mm=125,legend='Released versus animal-balanced PGLS coefficients using identical full24 log10 scaling. Whiskers are 95% t intervals. Full24 and exclusion of aeneus+wrighti are both shown. Specified conditional regressions do not establish causal direction.',alt_text='Coefficient forest compares genome-cell, cell-nucleus, and direct genome-nucleus conditional relationships under two species-summary definitions.'),
 d=list(plot=p4,title='Model support after resampling and species removal',width_mm=180,height_mm=130,legend='250 hierarchical animal-image-object draws under equal-animal summaries;24 leave-one-species-out fits using released summaries. Boxplots and points show candidate weights; labels count first ranks. Cross-assay resampling is independent. Single-animal species cannot estimate animal-level uncertainty.',alt_text='Weight distributions compare cell-bridge, genome-bridge, nucleus-bridge, and body-only hypotheses under two sensitivity procedures.')),
 width_mm=180,height_mm=365,datasets='Frozen S18/S21; Figure8 traits/scaling; frozen Path24 tree',legend=legend,alt_text='Four panels show animal support, effects of animal weighting, conditional coefficients, and model-weight sensitivity.')
